import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"概览","description":"MetaFusion 平台定位、核心特色与文档导航。","frontmatter":{"title":"概览","description":"MetaFusion 平台定位、核心特色与文档导航。","order":0,"group":"start"},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),i={name:"overview.md"};function n(s,t,l,d,h,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="平台概览" tabindex="-1">平台概览 <a class="header-anchor" href="#平台概览" aria-label="Permalink to &quot;平台概览&quot;">​</a></h1><p>MetaFusion 是一个<strong>开放媒体资源站与元数据共建平台</strong>，专注于 ACG、音乐、影视、文学等多元媒体资源的收录与结构化整理。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><blockquote><p><strong>公开元数据，受控媒体资源。</strong> 平台提供全量公开的元数据索引、结构化分类检索、自由词条编辑与社区贡献能力，并支持完整的开放 API 与 Agent 程序化调用。</p></blockquote><h2 id="目标群体" tabindex="-1">目标群体 <a class="header-anchor" href="#目标群体" aria-label="Permalink to &quot;目标群体&quot;">​</a></h2><ul><li><strong>普通用户</strong>：在探索页按虚拟货架、自由标签、Release 规格、创作者图谱发现优质作品与资源。</li><li><strong>编辑与共建者</strong>：基于 IFLA LRM 规范进行结构化编目，补充作品背景、外部权威链接与修订说明。</li><li><strong>开发者与 Agent</strong>：通过 MusicBrainz WS/2 风格的 Lookup / Browse / Search API 与 PAT 访问令牌，程序化调用全站能力。</li><li><strong>管理团队</strong>：通过后台审核、审计日志与系统开关维护社区秩序与合规运营。</li></ul><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><ul><li><strong>核心理念</strong>：开放元数据目录的建设原则与邀请机制</li><li><strong>快速上手</strong>：5 分钟完成注册、探索资源与创建第一条元数据</li><li><strong>资源体系</strong>：IFLA LRM 增强版实体模型、标签系统与虚拟货架体系</li><li><strong>编辑与投稿</strong>：词条创建、实体合并、分片上传与自适应流媒体转码</li><li><strong>开放 API</strong>：PAT 认证、实体查询、全文检索与 Agent 自动化接入</li><li><strong>服务与合规</strong>：服务条款、隐私政策、版权与 DMCA 处理机制</li></ul><h2 id="多系统解耦生态架构" tabindex="-1">多系统解耦生态架构 <a class="header-anchor" href="#多系统解耦生态架构" aria-label="Permalink to &quot;多系统解耦生态架构&quot;">​</a></h2><p>MetaFusion 整体采用**「元数据系统为主项目，周边外围子系统解耦自治」**的架构矩阵：</p><ul><li><strong>元数据核心系统 (metafusion-catalog)</strong>：<strong>主项目</strong>，聚焦于固定实体骨架（Agent, Collection, Work, ContentUnit, Expression, Release, Medium, Track）、动态定义引擎、关系图谱与审核修订历史。仅依赖 PostgreSQL 即可 100% 独立稳定运行。</li><li><strong>账号与身份认证中心 (metafusion-auth)</strong>：独立身份微服务，提供统一用户注册/登录、RBAC 权限管理、OAuth 2.0 / OIDC 认证授权与 JWT 统一鉴权。</li><li><strong>资源存储与下载管理中枢 (metafusion-storage)</strong>：独立物理文件归档、S3 分布式对象存储、哈希防篡改校验与种子/下载配额控制。</li><li><strong>社区交流与论坛系统 (metafusion-community)</strong>：独立讨论版块、主题回复与条目动态评分。</li><li><strong>API 网关与边缘路由 (metafusion-api-gateway)</strong>：统一单域名反向代理分发、TLS 证书终止与全域 OpenAPI 聚合。</li><li><strong>开发者文档站点 (metafusion-docs)</strong>：独立 VitePress 文档工程，承载对外规范、API 文档与 Agent 接入指引。</li></ul><h2 id="访问与权限模型" tabindex="-1">访问与权限模型 <a class="header-anchor" href="#访问与权限模型" aria-label="Permalink to &quot;访问与权限模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>权限要求</th><th>内容与能力</th></tr></thead><tbody><tr><td>基础元数据</td><td>开放浏览与检索</td><td>Work / Release / Medium / Track / Artist 详情、标签与货架体系、图谱网络、OpenSearch 全文搜索、社区公开讨论</td></tr><tr><td>资源操作</td><td>需登录用户</td><td>原档下载、音视频预览流播放、资源分片上传、发帖/回帖、私信交流、PAT 令牌管理</td></tr><tr><td>词条维护</td><td>需登录用户</td><td>新建作品/发行版/创作者、修改元数据、提交合并申请、查看修订历史</td></tr><tr><td>系统管理</td><td>管理员/考据员</td><td>站点配置、审核流转队列、板块管理、审计日志与数据统计</td></tr></tbody></table><h2 id="快速入口" tabindex="-1">快速入口 <a class="header-anchor" href="#快速入口" aria-label="Permalink to &quot;快速入口&quot;">​</a></h2><p>下一节：<a href="/docs/philosophy">核心理念与定位</a></p>',15)])])}const p=e(i,[["render",n]]);export{c as __pageData,p as default};
